+    // Reproduction for "ignore: parallel walker occasionally hangs if visitor
+    // panics". Based on the test in the report, with two differences: it
+    // fails (instead of hanging forever) if `run` has not returned after a
+    // deadline, and it only requires that `run` ends by panicking rather
+    // than requiring the original "oops!" payload. The thread count can be
+    // overridden with RECREATE_THREADS (default 40, as in the report).
+    #[test]
+    fn panic_in_parallel() {
+        use std::sync::mpsc;
+        use std::time::Duration;
+
+        let threads: usize = std::env::var("RECREATE_THREADS")
+            .ok()
+            .and_then(|v| v.parse().ok())
+            .unwrap_or(40);
+
+        // Use a private directory instead of TempDir so that a leftover
+        // `rust-ignore/N` directory from an earlier run cannot interfere.
+        let dir = std::env::temp_dir()
+            .join(format!("rust-ignore-panic-in-parallel-{}", std::process::id()));
+        let _ = fs::remove_dir_all(&dir);
+        mkdirp(&dir);
+        wfile(dir.join("foo.txt"), "");
+
+        let (tx, rx) = mpsc::channel();
+        let walk_dir = dir.clone();
+        std::thread::spawn(move || {
+            let result =
+                std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
+                    WalkBuilder::new(&walk_dir)
+                        .threads(threads)
+                        .build_parallel()
+                        .run(|| Box::new(|_| panic!("oops!")));
+                }));
+            let _ = tx.send(result.is_err());
+        });
+        let outcome = rx.recv_timeout(Duration::from_secs(10));
+        let _ = fs::remove_dir_all(&dir);
+
+        match outcome {
+            Ok(true) => {}
+            Ok(false) => panic!("run() returned normally; the panic was lost"),
+            Err(_) => panic!(
+                "run() did not return within 10s after the visitor \
+                 panicked ({} threads): hang",
+                threads
+            ),
+        }
+    }
+
